import pathlib,json,subprocess,time,fcntl,hashlib,base64,sys
root=pathlib.Path('/opt/tp-community-main-20261028')
helper=base64.b64decode('')
installer=base64.b64decode('')
namespace={};exec(compile(installer,'reviewed-scope-installer','exec'),namespace)
result={'operation':'repair-managed-scope-controllers','live_policy_manual_edits':False}
timers=['tp-http-scope.timer','tp-ha-scope.timer'];services=['tp-http-scope.service','tp-ha-scope.service'];containers=['tp-community-main-47-broker-owner-1','tp-community-main-47-broker-mosquitto-1']
def run(args):
 p=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True,timeout=95)
 if p.returncode:raise RuntimeError('command failed: '+args[0]+' '+args[1])
 return p.stdout.strip()
def snapshot():
 out=[]
 for n in containers:
  x=json.loads(run(['docker','inspect',n]))[0];out.append({'name':n,'image':x['Image'],'started':x['State']['StartedAt'],'restarts':x['RestartCount'],'status':x['State']['Status'],'health':x['State'].get('Health',{}).get('Status')})
 return out
stopped=[]
try:
 assert hashlib.sha256(pathlib.Path('/home/thingspanel/thingspanel-backend-community/thingspanel-backend-community').read_bytes()).hexdigest()=='99cf92bae98df01e78e97c01f6958351b48fe78a9a4b0dc70e321e0978840f4b','Gin deployment changed'
 before=snapshot();assert all(x['image']=='sha256:fd7091f1868a6642742315be959bb52db144d1416bf9fcf1a3455d068e24ec50' for x in before),'Broker deployment changed'
 # Validate exact code before stopping only these two timer triggers.
 for kind in ('http','ha'):namespace['patched_source'](kind,(root/(kind+'-runtime')/'scope.py').read_bytes())
 for timer in timers:
  status=run(['systemctl','show',timer,'--property=ActiveState','--value'])
  if status=='active':run(['systemctl','stop',timer]);stopped.append(timer)
 deadline=time.time()+100
 while any(run(['systemctl','show',s,'--property=ActiveState','--value']) in ('active','activating','deactivating') for s in services):
  if time.time()>deadline:raise RuntimeError('Existing controller did not finish; no forced termination')
  time.sleep(2)
 with pathlib.Path('/opt/tp-community-actions/deployment.lock').open('a') as lock:
  fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
  result['installed']=namespace['install'](root,helper)
 # Both timers remain stopped; each existing controller takes its own formal lock.
 for kind in ('http','ha'):
  run(['/usr/bin/python3.11',str(root/(kind+'-runtime')/'scope.py')])
 current=json.loads((root/'active-broker-services.private.json').read_text())
 app=next(x for x in current if x['username']=='tp-main47-platform')
 assert app.get('target_tenant_scope')=='platform' and app.get('target_scoped_publisher') is True and not app.get('allowed_device_ids') and not app.get('allowed_tenant_ids'),'Platform role failed to converge'
 for x in current:
  if x.get('plugin_socket'):assert not x.get('target_scoped_publisher') and not x.get('target_tenant_scope'),'Plugin inherited platform role'
 result['before']=before;result['after']=snapshot();result['status']='controllers-repaired'
 result['scope_summary']=[{'principal':x.get('principal',{}).get('device_id'),'plugin':bool(x.get('plugin_socket')),'role':x.get('target_tenant_scope'),'device_count':len(x.get('allowed_device_ids',[])),'tenant_count':len(x.get('allowed_tenant_ids',[]))} for x in current]
except Exception as e:result['status']='repair-failed';result['error']=type(e).__name__+': '+str(e)
finally:
 for timer in stopped:
  try:run(['systemctl','start',timer])
  except Exception:result.setdefault('timer_restore_errors',[]).append(timer)
 result['restored_timers']=stopped
print(json.dumps(result))
